const body = $input.first().json.body || $input.first().json;

const to       = body.to       || '';
const toName   = body.toName   || to.split('@')[0] || 'there';
const subject  = body.subject  || 'A message from Yellow Feather Books';
const bodyText = body.bodyText || '';
const type     = body.type     || 'general'; // 'author' | 'member' | 'general'

// Normalise phone for WhatsApp (91XXXXXXXXXX format)
const rawPhone = (body.phone || '').replace(/[^0-9]/g, '').replace(/^0+/, '');
const waPhone  = rawPhone.length === 10 ? '91' + rawPhone
               : rawPhone.startsWith('91') && rawPhone.length === 12 ? rawPhone
               : rawPhone;

// Convert plain-text body to HTML (preserve line breaks)
const htmlBody = bodyText
  .split('\n')
  .map(line => line.trim() ? `<p style="margin:0 0 12px;font-size:15px;color:#333;line-height:1.7;">${line}</p>` : '<br/>')
  .join('');

const emailHtml = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/></head>
<body style="margin:0;padding:0;background:#f4f4f4;font-family:Arial,sans-serif;">
<div style="max-width:620px;margin:32px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,0.08);">
  <div style="background:#1a1a2e;padding:24px 32px;text-align:center;">
    <img src="https://yellowfeather.netlify.app/logo-landscape.png" alt="Yellow Feather Books" height="44"
      onerror="this.style.display='none'" style="display:block;margin:0 auto;"/>
  </div>
  <div style="padding:36px 32px;">
    ${htmlBody}
  </div>
  <div style="background:#f5f0e8;padding:18px 32px;font-size:12px;color:#666;line-height:1.8;border-top:1px solid #e5e0d8;">
    Yellow Feather Books &nbsp;&middot;&nbsp;
    <a href="https://yellowfeather.netlify.app" style="color:#C9922A;">yellowfeather.netlify.app</a>
    &nbsp;&middot;&nbsp; +91 9400446565
  </div>
</div>
</body></html>`;

return [{ json: { to, toName, subject, bodyText, emailHtml, waPhone, type, hasPhone: waPhone.length >= 10 } }];
